import pytest

from refproj.inventory import Shelf, hold, release

FULL = Shelf(sku="W-1", on_hand=5, held=0)
PARTLY_HELD = Shelf(sku="W-1", on_hand=2, held=3)


def test_hold_moves_units_from_on_hand_to_held() -> None:
    assert hold(FULL, 3) == Shelf(sku="W-1", on_hand=2, held=3)


def test_release_moves_units_from_held_back_to_on_hand() -> None:
    assert release(PARTLY_HELD, 2) == Shelf(sku="W-1", on_hand=4, held=1)


def test_hold_then_release_follows_the_contract_example() -> None:
    assert release(hold(FULL, 3), 2) == Shelf(sku="W-1", on_hand=4, held=1)


def test_hold_returns_a_new_shelf_and_leaves_the_argument_untouched() -> None:
    shelf = Shelf(sku="W-1", on_hand=5, held=0)
    result = hold(shelf, 3)
    assert result is not shelf
    assert shelf == Shelf(sku="W-1", on_hand=5, held=0)


def test_release_returns_a_new_shelf_and_leaves_the_argument_untouched() -> None:
    shelf = Shelf(sku="W-1", on_hand=2, held=3)
    result = release(shelf, 2)
    assert result is not shelf
    assert shelf == Shelf(sku="W-1", on_hand=2, held=3)


def test_hold_of_all_that_is_on_hand_is_allowed() -> None:
    assert hold(FULL, 5) == Shelf(sku="W-1", on_hand=0, held=5)


def test_release_of_all_that_is_held_is_allowed() -> None:
    assert release(PARTLY_HELD, 3) == Shelf(sku="W-1", on_hand=5, held=0)


@pytest.mark.parametrize("quantity", [0, -1])
def test_hold_rejects_non_positive_quantity(quantity: int) -> None:
    with pytest.raises(ValueError, match="quantity must be positive"):
        hold(FULL, quantity)


@pytest.mark.parametrize("quantity", [0, -1])
def test_release_rejects_non_positive_quantity(quantity: int) -> None:
    with pytest.raises(ValueError, match="quantity must be positive"):
        release(PARTLY_HELD, quantity)


def test_cannot_hold_more_than_on_hand() -> None:
    with pytest.raises(ValueError, match="on hand"):
        hold(FULL, 6)


def test_cannot_release_more_than_held() -> None:
    with pytest.raises(ValueError, match="held"):
        release(PARTLY_HELD, 4)


def test_refused_hold_changes_nothing() -> None:
    shelf = Shelf(sku="W-1", on_hand=5, held=0)
    for quantity in (6, 0, -1):
        with pytest.raises(ValueError):
            hold(shelf, quantity)
    assert shelf == Shelf(sku="W-1", on_hand=5, held=0)


def test_refused_release_changes_nothing() -> None:
    shelf = Shelf(sku="W-1", on_hand=2, held=3)
    for quantity in (4, 0, -1):
        with pytest.raises(ValueError):
            release(shelf, quantity)
    assert shelf == Shelf(sku="W-1", on_hand=2, held=3)


def test_seam1_units_are_moved_not_made() -> None:
    # FULL carries 5 units in all; a hold and a release must each leave 5.
    after_hold = hold(FULL, 3)
    assert after_hold.on_hand + after_hold.held == 5
    after_release = release(after_hold, 2)
    assert after_release.on_hand + after_release.held == 5


def test_I1_nothing_on_the_shelf_is_ever_negative() -> None:
    starts = [
        Shelf(sku="W-1", on_hand=0, held=0),
        Shelf(sku="W-1", on_hand=5, held=0),
        Shelf(sku="W-1", on_hand=0, held=4),
        Shelf(sku="W-1", on_hand=2, held=3),
    ]
    sequences = [
        [(hold, 1), (hold, 5), (hold, 6), (hold, 1000)],
        [(release, 1), (release, 4), (release, 5), (release, 1000)],
        [(hold, 3), (release, 2), (hold, 4), (release, 5), (release, 6)],
        [(hold, 0), (release, 0), (hold, -1), (release, -1), (hold, -1000), (release, -1000)],
        [(hold, 5), (hold, 1), (release, 5), (release, 1), (hold, 2), (release, 3)],
        [(release, 3), (hold, 7), (hold, -7), (release, 7), (hold, 2), (release, -2)],
    ]
    for start in starts:
        for sequence in sequences:
            shelf = start
            for call, quantity in sequence:
                try:
                    shelf = call(shelf, quantity)
                except ValueError:
                    pass  # a refused call: the shelf stays as it was
                assert shelf.on_hand >= 0, (start, sequence, call.__name__, quantity)
                assert shelf.held >= 0, (start, sequence, call.__name__, quantity)

import pytest

from refproj.inventory import Shelf, hold, release

FULL = Shelf(sku="W-1", on_hand=5, held=0)
PARTLY_HELD = Shelf(sku="W-1", on_hand=2, held=3)


def test_hold_moves_units_from_on_hand_to_held() -> None:
    assert hold(FULL, 3) == Shelf(sku="W-1", on_hand=2, held=3)


def test_release_moves_units_from_held_back_to_on_hand() -> None:
    assert release(PARTLY_HELD, 2) == Shelf(sku="W-1", on_hand=4, held=1)


def test_hold_returns_a_new_shelf_and_leaves_the_argument_untouched() -> None:
    shelf = Shelf(sku="W-1", on_hand=5, held=0)
    after = hold(shelf, 3)
    assert after is not shelf
    assert shelf == Shelf(sku="W-1", on_hand=5, held=0)


def test_release_returns_a_new_shelf_and_leaves_the_argument_untouched() -> None:
    shelf = Shelf(sku="W-1", on_hand=2, held=3)
    after = release(shelf, 2)
    assert after is not shelf
    assert shelf == Shelf(sku="W-1", on_hand=2, held=3)


def test_hold_of_all_that_is_on_hand_is_allowed() -> None:
    assert hold(FULL, 5) == Shelf(sku="W-1", on_hand=0, held=5)


def test_release_of_all_that_is_held_is_allowed() -> None:
    assert release(PARTLY_HELD, 3) == Shelf(sku="W-1", on_hand=5, held=0)


@pytest.mark.parametrize("quantity", [0, -1])
def test_hold_of_a_non_positive_quantity_is_refused(quantity: int) -> None:
    with pytest.raises(ValueError, match="quantity must be positive"):
        hold(FULL, quantity)


@pytest.mark.parametrize("quantity", [0, -1])
def test_release_of_a_non_positive_quantity_is_refused(quantity: int) -> None:
    with pytest.raises(ValueError, match="quantity must be positive"):
        release(PARTLY_HELD, quantity)


def test_cannot_hold_more_than_on_hand() -> None:
    with pytest.raises(ValueError, match="on hand"):
        hold(FULL, 6)


def test_cannot_release_more_than_held() -> None:
    with pytest.raises(ValueError, match="held"):
        release(PARTLY_HELD, 4)


def test_a_refused_call_changes_nothing() -> None:
    shelf = Shelf(sku="W-1", on_hand=2, held=3)
    with pytest.raises(ValueError):
        hold(shelf, 3)
    with pytest.raises(ValueError):
        hold(shelf, 0)
    with pytest.raises(ValueError):
        release(shelf, 4)
    with pytest.raises(ValueError):
        release(shelf, -1)
    assert shelf == Shelf(sku="W-1", on_hand=2, held=3)


def test_seam1_units_are_moved_not_made() -> None:
    shelf = Shelf(sku="W-1", on_hand=5, held=2)
    after_hold = hold(shelf, 3)
    assert after_hold.on_hand + after_hold.held == 7
    after_release = release(after_hold, 4)
    assert after_release.on_hand + after_release.held == 7


@pytest.mark.parametrize(
    ("start", "calls"),
    [
        (
            Shelf(sku="W-1", on_hand=5, held=0),
            [("hold", 3), ("hold", 3), ("release", 2), ("release", 2), ("hold", 4), ("hold", 1)],
        ),
        (
            Shelf(sku="W-1", on_hand=0, held=0),
            [("hold", 1), ("release", 1), ("hold", 0), ("release", 0), ("hold", -7)],
        ),
        (
            Shelf(sku="W-1", on_hand=0, held=4),
            [("release", 5), ("release", 4), ("release", 1), ("hold", 4), ("hold", 1)],
        ),
        (
            Shelf(sku="W-1", on_hand=3, held=3),
            [("hold", -3), ("release", -3), ("hold", 1000000), ("release", 1000000), ("hold", 3)],
        ),
    ],
)
def test_I1_nothing_on_the_shelf_is_ever_negative(
    start: Shelf, calls: list[tuple[str, int]]
) -> None:
    shelf = start
    for name, quantity in calls:
        try:
            shelf = hold(shelf, quantity) if name == "hold" else release(shelf, quantity)
        except ValueError:
            pass
        assert shelf.on_hand >= 0
        assert shelf.held >= 0
